		"story": "[완전히 주관적인 바이노럴 속삭임 3자 섹스!] 매주 주말... 체력 유지를 위해 병동 테니스부를 만들었다. 아내는 아카리 가문의 젊은 아내 츠무기와 절친한 사이로, 거부할 수 없는 스트라이커다... \"야, 우리 같이 이 가문을 파괴하자...\" 땀 범벅이 된 츠무기가 내게 달라붙어 유혹하고, 음탕하고 생생한 혼외정사로 이어진다. 윤기 나는 머리카락이 몸에 달라붙고, 체액 냄새도 나고, 탄탄하고 유연한 아름다운 몸. 모든 것에 유혹당한다... \"오늘 밤 네 남편을 훈련시켜 줄게, 들키지 않게, 알았지?\" 악녀의 속삭임이 내 귀를 파고들고, 나는 몇 번이고 이성을 잃고 그녀의 안에 사정한다. 아내 옆에서 조용하고 냉정하게 놀림을 받으며 저항하는 것도 잊고, 결국 배신과 임신 사정으로 이어진다!",
